  + _mini(2, 'עסקה 2', 'הלוואה מהבנק 50,000', [_b('מזומן', '130,000', 'ca', 130)], [_b('הלוואה', '50,000', 'ncl', 50), _b('הון מניות', '80,000', 'eqb', 80)], 'נוסף מקור, ונוסף מזומן.')
  + _mini(3, 'עסקה 3', 'ציוד ב-120,000 במזומן', [_b('מזומן', '10,000', 'ca', 22), _b('ציוד', '120,000', 'nca', 108)], [_b('הלוואה', '50,000', 'ncl', 50), _b('הון מניות', '80,000', 'eqb', 80)], 'השימוש התחלף. המקורות לא זזו.')
  + '</div>'
