_tx1 = 'לכל חשבון שמשתנה כותבים את השינוי בשורה של העסקה: מספר חיובי כשהוא גדל, ומינוס כשהוא קטן. הבקרה (בעמודה האחרונה) מחשבת לבד נכסים פחות התחייבויות פחות הון, וצריכה להראות מקף, כלומר 0.'
_CH = {'a': 'נכסים:', 'l': 'התחייבויות:', 'e': 'הון עצמי:'}


def NTX(k, title, story, chips, accts=A1, base=0, build=None, note=None):
    """Transaction k of Noa (1 based) in the table of its phase: the rows before it are given, its row is the student's."""
    rows = NOA[base:k]
    sp = IDSHEET(accts, rows, [k - 1 - base])
    QT(f'x-n{k}', f'עסקה {k}', title, [story], _tx1, sp, chips=[(c, _CH[c], t) for c, t in chips], note=note, build=build,
       done='הבקרה מראה 0: המאזן מאוזן גם אחרי העסקה.', xtitle=f'עסקה {k}: {title}')


